function nextSpNo(){ const d=new Date(); DB.spSeq=(DB.spSeq||100)+1; return 'HT'+String(d.getFullYear()).slice(2)+pad(d.getMonth()+1)+pad(d.getDate())+String(DB.spSeq%10000).padStart(4,'0'); }

