const spAddImgs = (list, input, after) => { const room=10-list.length; if(room<=0){ toast(t('sp_max_files'),'bad'); return; } const files=[...input.files].slice(0,room); readFiles({files, set value(v){}}, 'image', arr=>{ list.push(...arr); after(arr); }); };
